INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cat Detective Albert Wilde', 'Cat Detective Albert Wilde is a comedy game, a genre-bending noirish sci-fi mystery set in a fictional version of New York in the 1930''s featuring atmospheric black & white vintage visuals, and loveable anthropomorphic characters. Players must muddle their way through a murder mystery that''s messier than a fresh hairball, with a captivating voice-over and at least one joke about cat nipples (they have six!).' FROM games WHERE igdb_id = 191800 ON CONFLICT (game_id, language_code) DO NOTHING;
