INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stolen Blood', 'Stolen Blood is a first-person mystical horror game inspired by European folklore. Haunted by visions, you uncover a tragic past of family, curses, and death. These visions flow from your very blood—they call to you. Once you understand your past, only one question remains: whose soul will you save?' FROM games WHERE igdb_id = 341452 ON CONFLICT (game_id, language_code) DO NOTHING;
