INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoru ga Kuru!: Square of the Moon - Remastered', 'Ryou lives a dull life in Otsuna until a red-eyed girl named Izumi invites him to join her fight against the Light Hunters. When the True Moon rises, the Light Hunters descend upon the city, leaving chaos in their wake. Cloaked in the shadows of the night, this story of supernatural suspense begins.' FROM games WHERE igdb_id = 298383 ON CONFLICT (game_id, language_code) DO NOTHING;
