INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('trophy-trout', 43150, '2025-07-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7kjl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2os3.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trophy Trout', 'Trophy Trout is a first person simulation where the player levels up, goes fishing and has fun. Enjoy maps of fishing holes on real rivers, models of authentic trophy fish and actual hatches changing by season. Real life strategies and tactics are used to catch fish in the game. The game was created by a single person, Mac Clark, a fly fishing guide in the northwest and is built using the award winning Unreal Game Engine.' FROM games WHERE igdb_id = 43150 ON CONFLICT (game_id, language_code) DO NOTHING;
