INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pond', 'Build. Customize. Relax. Create your own peaceful fish pond and watch it come alive, piece by piece. Shape the terrain and decorate your pond the way you like. Place fish and see them swim around in their new home. No stress—just a soothing world where you can enjoy the beauty of nature.' FROM games WHERE igdb_id = 373662 ON CONFLICT (game_id, language_code) DO NOTHING;
