INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'O.W.L.: One Wave Length', 'OWL is top down, rogue like bullet-hell that you can play with up to 1 friend. Everything is in beat, including your and the enemies attacks. With each new Instrument, new attack patterns unfold for you which will take you to your final obstacle; The Meowestro, the source of dissonance.' FROM games WHERE igdb_id = 341579 ON CONFLICT (game_id, language_code) DO NOTHING;
