INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hexitten', 'Hexitten is a sci-fi roguelike deck builder with tactical grid based battles. You will build an elite team of heroes to tackle the greatest threats to the galactic alliance. During your campaign, you will travel through the 6 hextants of the galaxy to collect new abilities, modify your ships, recruit additional team members, discover each hero''s story and increase their synergy with other heroes, encounter special events, and fight for the future of the alliance.' FROM games WHERE igdb_id = 343668 ON CONFLICT (game_id, language_code) DO NOTHING;
