INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love to Live', 'Trapped in a game of dreams, where the price of failing to escape is eternal slumber. Across shifting worlds, you meet ''him.'' Is he merely a kindred spirit born of crisis, or a forgotten soul from your distant memories? A heart-pounding romance adventure across the dreamscape—begins now!' FROM games WHERE igdb_id = 346860 ON CONFLICT (game_id, language_code) DO NOTHING;
