INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmare Frontier', 'Behold the first-ever Tactical Extraction Looter where you pit your courage and leadership against fears made manifest: the Dreadweavers. Lead a band of scavenger roughnecks into a devastated boom town of the alternative 1900s. Get in, face the monsters, grab what you can carry and get out. Alive.' FROM games WHERE igdb_id = 342784 ON CONFLICT (game_id, language_code) DO NOTHING;
