INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Path Home', '"The Path Home" is a 2D pixel-art puzzle game where you explore a strange world with a girl. Use panels to "flip" black and white tiles and reshape the puzzle world. The girl always searches for the "shortest path to the goal," but avoiding fake goals and reuniting her with the crow is up to you.' FROM games WHERE igdb_id = 372934 ON CONFLICT (game_id, language_code) DO NOTHING;
