INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Despelote', 'Despelote is a soccer game about people. Get immersed in the streets and parks of Quito through the eyes and ears of eight year old Julián. Dribble, pass and shoot your soccer ball around town, and see what happens when you kick it someone''s way. Feel the city change as Ecuador comes closer than ever to qualifying for the World Cup.' FROM games WHERE igdb_id = 145070 ON CONFLICT (game_id, language_code) DO NOTHING;
