INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glint''s Trial', 'Take control of Glint, a glowing explorer on a mission through 15 pixel-perfect platforming levels filled with deadly traps and quirky enemies. Inspired by classic retro games, Glint’s Trial delivers tight controls, charming pixel art, and speedrun-ready challenges. Whether you''re hopping past spikes or dodging fishes every level is a handcrafted test of reflexes and memory. Can you survive the trial and prove you''re a true retro platforming master? A game developed by CraePlay and ported by GGmuks' FROM games WHERE igdb_id = 356156 ON CONFLICT (game_id, language_code) DO NOTHING;
