INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vice Thief Simulator: 80s Nostalgia', 'Dive into the neon-lit 80s and become a cunning thief! Break into houses, steal valuables, hijack cars, and escape the cops. Upgrade your skills and gear to survive in a world where only the boldest criminals thrive.' FROM games WHERE igdb_id = 365344 ON CONFLICT (game_id, language_code) DO NOTHING;
