INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gomiboru', 'Gomiboru is an arcade-puzzle game set in Stampland, a decaying amusement park. Guide a strange sticky ball as it collects the trash scattered throughout the environments, solving physics puzzles and facing absurd obstacles. Unravel the mystery behind the chaos in a dark and surreal world.' FROM games WHERE igdb_id = 333017 ON CONFLICT (game_id, language_code) DO NOTHING;
