INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JoshGeoff Weiner Simulator', 'JoshGeoff Weiner Simulator is a quirky and humorous simulation game that lets players step into the shoes of JoshGeoff''s unique worker, a character navigating through bizarre cities and locations. Set in the UK, the game blends elements of exploration and interaction with an emphasis on comedic storytelling and quirky dialogue. Players are tasked with completing unusual challenges, all while collecting things for your boss.' FROM games WHERE igdb_id = 327837 ON CONFLICT (game_id, language_code) DO NOTHING;
