INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Scream Ice Cream', 'I Scream Ice Cream is a physics-based action game where players control an Ice Cream Soul through 30 levels using voice commands. Players navigate obstacles by literally shouting "Ice Cream" into their microphone, creating a unique voice-controlled gameplay experience that combines precision movement with audio input.' FROM games WHERE igdb_id = 358298 ON CONFLICT (game_id, language_code) DO NOTHING;
