INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turned Into Turrets', 'Once human, now machines forged by fake love. You just have five minutes to take down the waves of monsters and discover the path back to humanity. Turned Into Turrets is a 2D top-down roguelike game where you stand as a living turret, fighting waves of enemies with automatic attacks and builds.' FROM games WHERE igdb_id = 377082 ON CONFLICT (game_id, language_code) DO NOTHING;
