INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dear me, I was…', 'Dear me, I was… is an interactive adventure that lets you enjoy a story woven with beautiful visuals, fusing the vibrant watercolor style of Taisuke Kanasaki with rotoscoping technology.
