INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Spider: Vengeance Remastered', 'Fully voiced, with over 530 CGs, and an estimated total playtime of 7-8 hours (approx. 1 hour per route). Homages to classic Hong Kong films and characters based on real-life famous actors immerse you in a deep, cinematic drama. The "Cyclopedia" included in the game provides detailed explanations of which scenes reference which films, and which characters are inspired by which actors.' FROM games WHERE igdb_id = 371969 ON CONFLICT (game_id, language_code) DO NOTHING;
