INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fever Meme', 'Fever Meme is a comedy/parody game that pivots between multiple genres as it spits in the face of traditional game design. The game is self-aware of your actions as you play, your past mistakes, and so much more. And the further you make it into the game, the more the dynamic between player and creator is explored as the fourth wall is completely stripped away.' FROM games WHERE igdb_id = 350483 ON CONFLICT (game_id, language_code) DO NOTHING;
