INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Light Up the Town', 'Light Up The Town is a cozy, casual holiday game for all ages. Play as Bean, a precocious young ferret, and explore the town of Bellflower, Colorado as you hang up festive string lights around to spread holiday cheer. Click to throw a light or decoration; the only limit is your imagination.' FROM games WHERE igdb_id = 348596 ON CONFLICT (game_id, language_code) DO NOTHING;
