INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deja View: A Spot the Difference Game', 'Dive into surreal worlds in Deja View, a relaxing yet challenging spot-the-difference puzzle game. Explore 16 hand-drawn, mind-bending illustrations, each split into two intricate halves. Earn hints, unlock achievements, and immerse yourself in an enchanting soundtrack along your journey.' FROM games WHERE igdb_id = 344290 ON CONFLICT (game_id, language_code) DO NOTHING;
