INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('five-nights-at-freddys-secret-of-the-mimic', 312859, '2025-06-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9x7x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3o65.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Five Nights at Freddy''s: Secret of the Mimic', 'Enter the abandoned workshop of Murray’s Costume Manor and unravel the mystery left behind by the reclusive inventor, Edwin Murray. In Five Nights at Freddy’s: Secret of the Mimic, you’ll step into a world where every dark corner holds a secret and every flicker of light hints at an ever-present threat. The Mimic, a prototype endoskeleton, can adapt to any costume and become any character, including what you fear most. Armed with only your wits, a few gadgets, and a heavily redacted corporate briefing, you’ll attempt to retrieve Fazbear’s prized prototype technology while grappling with cryptic clues and a relentless shadow determined to dispatch all unwanted company.
