INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sudoku Touch', 'Sudoku Touch is a modern take on the classic 9x9 logic puzzle. Designed for touch devices, it offers intuitive controls, multiple difficulty levels, and smart features like pencil mode, error checking, and dark mode. Whether you''re a beginner or a seasoned Sudoku master, Sudoku Touch provides a relaxing and brain-boosting experience.' FROM games WHERE igdb_id = 88415 ON CONFLICT (game_id, language_code) DO NOTHING;
