INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Menticide', 'Menticide is an endless runner where you protect a man running from himself. You draw lines to bounce the man around, block off enemies and cut through obstacles. Through strong symbolism and procedural rhetoric we are using the game as an analogue for mental health.' FROM games WHERE igdb_id = 329201 ON CONFLICT (game_id, language_code) DO NOTHING;
