INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marked: The Quest for Tripura', 'A single player puzzle exploration game where you play as Dee, short for Drauni, explore the ruins of Hampi, solving turn based puzzles, to find a way to escape your past and make it to the lost cities of Tripura. The puzzles reveal the origins of Chess and the long buried secrets of your ancestors.' FROM games WHERE igdb_id = 294355 ON CONFLICT (game_id, language_code) DO NOTHING;
